public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int L = sc.nextInt();
        int R = sc.nextInt();

        StringBuilder result = new StringBuilder();

        for(int i = L; i <= R; i++) {
            if(i < 2) continue;

            boolean isPrime = true;

            for(int j = 2; j * j <= i; j++) {
                if(i % j == 0) {
                    isPrime = false;
                    break;
                }
            }

            if(isPrime) {
                result.append(i).append(" ");
            }
        }

        System.out.print(result.toString().trim());
    }
}

