public class Main {

    static void rotate(int[] arr, int k) {
        int n = arr.length;
        k = k % n;

        int[] result = new int[n];

        for(int i = 0; i < n; i++) {
            result[(i + k) % n] = arr[i];
        }

        for(int num : result) {
            System.out.print(num + " ");
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int[] arr = new int[n];

        for(int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        int k = sc.nextInt();

        rotate(arr, k);
    }
}

